CREATE TABLE IF NOT EXISTS product_brands (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', parent_id TEXT REFERENCES product_categories(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_tags (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_tag_links (product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES product_tags(id) ON DELETE CASCADE, PRIMARY KEY (product_id, tag_id));
CREATE TABLE IF NOT EXISTS product_attributes (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, display_type TEXT NOT NULL DEFAULT 'select' CHECK (display_type IN ('select','text','color')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_attribute_values (id TEXT PRIMARY KEY, attribute_id TEXT NOT NULL REFERENCES product_attributes(id) ON DELETE CASCADE, value TEXT NOT NULL, slug TEXT NOT NULL, UNIQUE(attribute_id, value));
CREATE TABLE IF NOT EXISTS product_reviews (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, order_id TEXT REFERENCES orders(id) ON DELETE SET NULL, customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), created_at TEXT NOT NULL, approved_at TEXT);
CREATE INDEX IF NOT EXISTS idx_product_reviews_public ON product_reviews(product_id,status,verified,created_at DESC);
